"""GigaChatModel — PydanticAI Model implementation backed by the gigachat SDK."""

from __future__ import annotations

from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from datetime import datetime, timezone
from typing import Any, Literal

from pydantic_ai.messages import ModelMessage, ModelResponse
from pydantic_ai.models import Model, ModelRequestParameters, StreamedResponse
from pydantic_ai.settings import ModelSettings
from pydantic_ai.usage import RequestUsage

from pydantic_ai_gigachat._mappers import (
    map_finish_reason,
    messages_to_gigachat,
    parts_from_gigachat_message,
    tools_to_gigachat,
    usage_from_gigachat,
)
from pydantic_ai_gigachat._stream import GigaChatStreamedResponse
from pydantic_ai_gigachat.provider import GigaChatProvider

DEFAULT_MODEL = "GigaChat"

# Subset of OpenAI-shaped knobs that GigaChat accepts on /chat/completions.
_PASSTHROUGH_SETTINGS = {
    "temperature",
    "top_p",
    "max_tokens",
    "n",
    "repetition_penalty",
    "update_interval",
    "profanity_check",
}


class GigaChatModel(Model):
    """A PydanticAI Model backed by the official ``gigachat`` SDK.

    All HTTP, OAuth, retry, and TLS concerns live in the SDK. This class is the
    PydanticAI ``Model`` adapter: translate ``ModelMessage`` lists into the
    SDK's payload shape, run the call, and translate typed responses back into
    ``ModelResponse`` / streaming events.

    Parameters
    ----------
    model_name:
        GigaChat model identifier. Examples: ``GigaChat``, ``GigaChat-Pro``,
        ``GigaChat-Max``, ``GigaChat-2``, ``GigaChat-2-Pro``, ``GigaChat-2-Max``.
    provider:
        A configured :class:`GigaChatProvider`. The provider owns the SDK
        client lifecycle.
    """

    # Override the looser ``Provider[InterfaceClient]`` annotation from the base
    # class so mypy can see GigaChat-specific provider methods.
    _provider: GigaChatProvider

    def __init__(
        self,
        model_name: str = DEFAULT_MODEL,
        *,
        provider: GigaChatProvider,
    ) -> None:
        self._model_name = model_name
        self._provider = provider

    # ------------------------------------------------------------------ meta

    @property
    def model_name(self) -> str:
        return self._model_name

    @property
    def system(self) -> Literal["gigachat"]:
        return "gigachat"

    @property
    def base_url(self) -> str:
        return self._provider.base_url

    # ------------------------------------------------------------------ api

    async def request(
        self,
        messages: list[ModelMessage],
        model_settings: ModelSettings | None,
        model_request_parameters: ModelRequestParameters,
    ) -> ModelResponse:
        payload = self._build_payload(messages, model_settings, model_request_parameters)
        completion = await self._provider.client.achat(payload)

        if not completion.choices:
            raise RuntimeError(f"GigaChat returned no choices: {completion!r}")
        choice = completion.choices[0]
        usage_counts = usage_from_gigachat(completion.usage)

        return ModelResponse(
            parts=parts_from_gigachat_message(choice.message),
            usage=RequestUsage(
                input_tokens=usage_counts["input_tokens"],
                output_tokens=usage_counts["output_tokens"],
                cache_read_tokens=usage_counts["cache_read_tokens"],
            ),
            model_name=completion.model or self._model_name,
            timestamp=datetime.fromtimestamp(completion.created, tz=timezone.utc),
            provider_name="gigachat",
            provider_url=self._provider.base_url,
            provider_response_id=completion.message_id,
            finish_reason=map_finish_reason(choice.finish_reason),
        )

    async def count_tokens(
        self,
        messages: list[ModelMessage],
        model_settings: ModelSettings | None,
        model_request_parameters: ModelRequestParameters,
    ) -> RequestUsage:
        """Pre-flight token count via the SDK's ``atokens_count``.

        Sends each message's ``content`` as a separate string and sums the
        per-string token counts. Deliberately ignores the small constant
        overhead of role markers and JSON envelope structure that the real
        chat call will add — close enough for budget-checking before the call.
        """
        del model_settings, model_request_parameters
        payload_messages = messages_to_gigachat(messages)
        inputs = [
            m["content"]
            for m in payload_messages
            if isinstance(m.get("content"), str) and m["content"]
        ]
        if not inputs:
            return RequestUsage(input_tokens=0, output_tokens=0)

        results = await self._provider.client.atokens_count(inputs, model=self._model_name)
        total = sum(item.tokens for item in results)
        return RequestUsage(input_tokens=total, output_tokens=0)

    @asynccontextmanager
    async def request_stream(
        self,
        messages: list[ModelMessage],
        model_settings: ModelSettings | None,
        model_request_parameters: ModelRequestParameters,
        run_context: Any | None = None,
    ) -> AsyncIterator[StreamedResponse]:
        payload = self._build_payload(messages, model_settings, model_request_parameters)

        chunk_iterator = self._provider.client.astream(payload).__aiter__()
        stream = GigaChatStreamedResponse(
            model_name=self._model_name,
            provider_name="gigachat",
            provider_url=self._provider.base_url,
            chunk_iterator=chunk_iterator,
            model_request_parameters=model_request_parameters,
        )
        yield stream

    # ------------------------------------------------------------------ internals

    def _build_payload(
        self,
        messages: list[ModelMessage],
        settings: ModelSettings | None,
        params: ModelRequestParameters,
    ) -> dict[str, Any]:
        """Build the dict payload accepted by ``GigaChat.achat`` / ``astream``.

        We pass ``dict`` (not the SDK's typed ``Chat`` model) so the JSON Schema
        for tool parameters survives unchanged — the typed ``FunctionParameters``
        model would coerce nested schema features lossily.
        """
        payload: dict[str, Any] = {
            "model": self._model_name,
            "messages": messages_to_gigachat(messages),
        }

        tools = list(params.function_tools)
        if params.output_tools:
            tools.extend(params.output_tools)
        if tools:
            payload["functions"] = tools_to_gigachat(tools)
            # Force tool use when the agent wants a structured tool-shaped output.
            if params.output_mode == "tool" and params.output_tools:
                payload["function_call"] = {"name": params.output_tools[0].name}
            else:
                payload["function_call"] = "auto"

        if settings:
            for key in _PASSTHROUGH_SETTINGS:
                value = settings.get(key)
                if value is not None:
                    payload[key] = value
            extra_body = settings.get("extra_body")
            if isinstance(extra_body, dict):
                payload.update(extra_body)

        return payload


__all__ = ["GigaChatModel", "DEFAULT_MODEL"]
